import{Engine,esc}from'./base.js';
export default class Diagram extends Engine{
 constructor(h,c){super(h,c);this.seen=new Set;this.selected=c.chapter.diagram.nodes[0].id;h.innerHTML=`<p>${c.dual('Select a card, then follow its connections. Arrows show relationships rather than physical distance.','कार्ड चुनें, फिर उसके संबंधों पर जाएँ। तीर संबंध बताते हैं, वास्तविक दूरी नहीं।')}</p><div class="diagramNodes"></div><article class="diagramDetail" aria-live="polite"></article>`;this.on(h,'click',e=>{let b=e.target.closest('[data-node]');if(b){if(b.hasAttribute('data-link'))this.metrics.connections=(this.metrics.connections||0)+1;this.select(b.dataset.node)}});this.render()}
 select(id){this.selected=id;this.seen.add(id);this.metrics.visited=this.seen.size;this.render();this.emit(this.ctx.text(this.ctx.chapter.diagram.nodes.find(n=>n.id===id).body))}
 render(){let c=this.ctx,nodes=c.chapter.diagram.nodes,n=nodes.find(n=>n.id===this.selected);this.host.querySelector('.diagramNodes').innerHTML=nodes.map((x,i)=>`<button data-node="${esc(x.id)}" aria-pressed="${x.id===this.selected}"><span class="nodeNumber">${i+1}</span>${c.label(x.title.en,x.title.hi)}</button>`).join('');this.host.querySelector('.diagramDetail').innerHTML=c.H(n.title,3)+`<p>${esc(c.text(n.body))}</p><div class="diagramLinks">${(n.next||[]).map(id=>{let next=nodes.find(x=>x.id===id);return next?`<button data-link data-node="${esc(id)}">→ ${c.label(next.title.en,next.title.hi)}</button>`:''}).join('')}</div>`}
 run(){this.schedule(()=>{let nodes=this.ctx.chapter.diagram.nodes,i=nodes.findIndex(n=>n.id===this.selected);this.select(nodes[(i+1)%nodes.length].id);this.run()},4000)}resetView(){this.selected=this.ctx.chapter.diagram.nodes[0].id;this.render()}
}
